-- 在现有省级行政区划上补充市、区、街道。
-- name 写入完整名称，short_name 写入简称，letter 写入拼音前缀。
-- adcode：省市区取原始编号前 6 位，街道取前 9 位。
-- 已有省保留原主键和区划编码。缺级补齐且编码与上级相同的记录，在短编号后补 000。

ALTER TABLE `sys_area`
  ADD COLUMN `short_name` varchar(32) NOT NULL DEFAULT '' COMMENT '简称' AFTER `name`,
  ADD COLUMN `deep` tinyint DEFAULT NULL COMMENT '层级深度，0省，1市，2区，3镇' AFTER `short_name`,
  ADD COLUMN `pinyin` varchar(64) NOT NULL DEFAULT '' COMMENT '完整拼音' AFTER `letter`,
  MODIFY COLUMN `area_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '区划类型，0国家，1省，2城市，3区县，4街道';

